/* Main menu */
.menu-card{width:min(900px,calc(100% - 28px));max-height:calc(100% - 28px);overflow:auto;padding:clamp(20px,4vw,42px);background:linear-gradient(135deg,rgba(24,30,40,.97),rgba(17,19,29,.98));border-color:#6f5c46;}
.menu-card:before{width:100%;height:2px;background:linear-gradient(90deg,#ffcf74,transparent 72%)}
.menu-layout{display:grid;grid-template-columns: minmax(220px,.9fr) minmax(300px,1.1fr);gap:clamp(18px,4vw,42px);align-items:center}
.menu-art{position:relative;min-height:320px;display:grid;place-items:center;overflow:hidden;background:radial-gradient(ellipse,#344038 0%,#1b292e 48%,#151b26 77%);border:1px solid #59604f;box-shadow:inset 0 0 50px #090d13}
.menu-art:after{content:'';position:absolute;inset:auto 0 0;height:35%;background:linear-gradient(transparent,#131923)}
.cat-art{width:min(86%,310px);height:auto;image-rendering:pixelated;filter:drop-shadow(0 14px 0 #111820) drop-shadow(0 0 22px #f4c66b44);animation:cat-float 3s ease-in-out infinite}
@keyframes cat-float{50%{transform:translateY(-7px)}}
.menu-stamp{position:absolute;left:14px;top:14px;color:#edcf91;font:9px 'DM Mono',monospace;letter-spacing:.18em;z-index:1}
.menu-title{font-size:clamp(34px,6vw,60px)!important;letter-spacing:-.065em!important;line-height:.9!important;margin:10px 0 12px!important}
.menu-title em{display:block;color:var(--gold);font-size:.77em;margin-top:8px}
.menu-subtitle{font:10px 'DM Mono',monospace!important;letter-spacing:.13em;text-transform:uppercase;color:#b9b4a8!important;margin:0 0 20px!important}
.menu-buttons{display:grid;grid-template-columns:1fr 1fr;gap:9px}
.menu-button{min-height:48px;padding:12px;background:#252b35;color:#f2e8d1;border:1px solid #49505a;text-align:left;font:600 10px 'DM Mono',monospace;letter-spacing:.08em;text-transform:uppercase;cursor:pointer;transition:background .16s,border-color .16s,transform .16s}
.menu-button:hover,.menu-button:focus-visible{outline:none;background:#343840;border-color:var(--gold);transform:translateY(-2px)}
.menu-button.primary{grid-column:1/-1;background:var(--gold);border-color:#ffdc9b;color:#211b18;text-align:center;font-size:12px;letter-spacing:.16em}
.menu-button .menu-icon{color:var(--gold);font-size:15px;margin-right:8px}
.menu-button.primary .menu-icon{color:#211b18}
.menu-foot{margin-top:16px;color:#858995;font:9px 'DM Mono',monospace;letter-spacing:.1em;line-height:1.6}
.menu-panel h1{font-size:clamp(30px,5vw,46px);margin:10px 0}
.menu-panel .panel-back{margin-top:15px;background:transparent;border:0;color:#d2bd94;font:10px 'DM Mono',monospace;letter-spacing:.12em;text-transform:uppercase;padding:10px 0;cursor:pointer}
.menu-panel .panel-back:hover{color:#fff}
.menu-options{display:grid;gap:9px;margin:16px 0}
