const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const pages = await (await fetch('http://127.0.0.1:9223/json')).json();
  const page = pages.find(x => x.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let id = 0;
  const pending = new Map();
  ws.onmessage = event => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  };
  const send = (method, params={}) => new Promise(resolve => {
    const next = ++id; pending.set(next, resolve); ws.send(JSON.stringify({id: next, method, params}));
  });
  const evalJS = async expression => {
    const result = await send('Runtime.evaluate', {expression, returnByValue:true, awaitPromise:true});
    if (result.error || result.result?.exceptionDetails) throw new Error(JSON.stringify(result));
    return result.result.result.value;
  };
  await send('Page.enable');
  await send('Page.navigate', {url:'http://127.0.0.1:8765/'});
  await sleep(900);
  const checks=[];
  const check=async (name,expr,expected)=>{const actual=await evalJS(expr);checks.push([name,actual,expected]);if(actual!==expected)throw new Error(`${name}: got ${actual}, expected ${expected}`)};
